const B=(text,action,value='',cls='')=>'<button type="button" class="f21-btn '+cls+'" data-f21="'+action+'" data-value="'+E(value)+'">'+text+'</button>';
const input=(label,id,value='',type='text',extra='')=>'<label class="f21-field"><span>'+label+'</span><input id="'+id+'" type="'+type+'" value="'+E(value)+'" '+extra+'></label>';
