const note=s=>'<div class="f21-note">'+s+'</div>',fold=(title,body)=>'<details class="f21-fold"><summary>'+title+'<span aria-hidden="true">+</span></summary><div>'+body+'</div></details>';
const table=(heads,rows)=>'<div class="f21-table"><table><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+(rows||'<tr><td colspan="'+heads.length+'"><div class="f21-empty">لا توجد سجلات ضمن هذا الاختيار.</div></td></tr>')+'</tbody></table></div>';
const statusName=s=>({legacy:'بحاجة إلى مراجعة',draft:'مسودة',review:'بانتظار الإدارة',posted:'معتمد',cancelled:'ملغى'})[s]||s;
