let view='home',form=null,busy=false,returnFocus=null,query='',filter='open',pageN=1,printContent='';
function toast(s,bad=false){let n=Q('f21Toast');if(!n){n=document.createElement('div');n.id='f21Toast';n.setAttribute('role','status');document.body.append(n);}n.className=bad?'bad':'';n.textContent=s;n.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.hidden=true,6500);}
function modal(title,body,footer='',ctx=null){returnFocus=document.activeElement;Q('f21Modal')?.remove();form=ctx;const n=document.createElement('div');n.id='f21Modal';n.className='f21-modal-back f21';n.innerHTML='<section class="f21-dialog" role="dialog" aria-modal="true" aria-labelledby="f21ModalTitle"><header><div><small>MOSH GROUP · المحاسبة</small><h2 id="f21ModalTitle">'+E(title)+'</h2></div>'+B('×','close','','icon')+'</header><div class="f21-modal-body">'+body+'</div><div id="f21Error" role="alert" hidden></div><footer>'+footer+B(ctx?'إلغاء':'إغلاق','close')+'</footer></section>';document.body.append(n);n.querySelector('input,select,textarea,button')?.focus();}
async function close(force=false){if(busy&&!force)return;if(form?.dirty&&!force&&!await ask('إغلاق النموذج دون حفظ التعديلات؟'))return;Q('f21Modal')?.remove();form=null;if(returnFocus?.isConnected)returnFocus.focus();}
function ask(text){return new Promise(resolve=>{const n=document.createElement('div');n.className='f21-modal-back f21 f21-confirm';n.innerHTML='<section class="f21-dialog" role="alertdialog" aria-modal="true"><header><h3>تأكيد الإجراء</h3></header><div class="f21-modal-body">'+E(text)+'</div><footer><button class="f21-btn primary" type="button" data-ok>تأكيد</button><button class="f21-btn" type="button" data-no>إلغاء</button></footer></section>';document.body.append(n);n.querySelector('[data-no]').focus();n.onclick=e=>{if(e.target.closest('[data-ok],[data-no]')){const ok=!!e.target.closest('[data-ok]');n.remove();resolve(ok);}};});}
function fail(e){const text=e?.message||String(e);if(Q('f21Error')){Q('f21Error').textContent=text;Q('f21Error').hidden=false;}else toast(text,true);}
const V=id=>T(Q(id)?.value);
function mount(){const host=Q('accountingApp');if(!host||Q('f21Layout'))return;const layout=document.createElement('div');layout.id='f21Layout';layout.className='f21-layout';const nav=document.createElement('nav');nav.id='f21Rail';nav.className='f21-rail';nav.setAttribute('aria-label','خدمات المحاسبة');nav.innerHTML='<b>'+svg('cash')+'المحاسبة</b><small>العملاء والفوترة</small>'+[['packages','قائمة الباقات','box'],['billing','مهام بانتظار الفوترة','file'],['invoices','فواتير العملاء والتحصيل','people']].map(([v,t,i])=>B(svg(i)+'<span>'+t+'</span>','nav',v)).join('')+'<small>المصروفات والالتزامات</small>'+[['vendors','الموردون والمشتريات','box'],['employees','مستحقات الموظفين','people'],['expenses','المصاريف','file']].map(([v,t,i])=>B(svg(i)+'<span>'+t+'</span>','nav',v)).join('')+'<small>الأموال والسجلات</small>'+[['cash','الصندوق والبنك','cash'],['reports','التقارير وكشوف الحساب','chart'],['settings','إعدادات المحاسبة','settings']].map(([v,t,i])=>B(svg(i)+'<span>'+t+'</span>','nav',v)).join('')+B(svg('file')+'<span>إرسال تقرير للإدارة</span>','exec');const body=document.createElement('div');body.className='f21-body';body.id='f21Body';const mobile=document.createElement('div');mobile.className='f21-mobile-nav f21';mobile.innerHTML='<label class="f21-field"><span>خدمات المحاسبة</span><select id="f21MobileNav" aria-label="الانتقال بين صفحات المحاسبة"><option value="home">لوحة التحكم</option>'+[...nav.querySelectorAll('[data-f21=nav]')].map(b=>'<option value="'+E(b.dataset.value)+'">'+E(b.textContent)+'</option>').join('')+'</select></label>';layout.append(nav,mobile,body);host.append(layout);['accountingTasksContent','accountingPackagesContent','accountingBillingContent','accountingInvoicesContent'].forEach(id=>{const n=Q(id);if(n)body.append(n);});const p=document.createElement('div');p.id='f21Page';p.className='f21';body.prepend(p);host.querySelectorAll(':scope>.menu-strip').forEach(n=>n.hidden=true);}
function navActive(v){if(Q('f21MobileNav'))Q('f21MobileNav').value=['payables','review','running'].includes(v)?'home':v;Q('f21Rail')?.querySelectorAll('[data-f21=nav]').forEach(b=>{const on=b.dataset.value===v;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
