function head(title,sub,actions=''){return'<div class="f21-heading"><div><span class="f21-eyebrow">قسم المحاسبة</span><h2>'+title+'</h2><p>'+sub+'</p></div><div class="f21-actions">'+actions+'</div></div>';}
function metric(title,n,v,sub=''){return B('<span>'+title+'</span><strong>'+E(n)+'</strong><small>'+sub+'</small>','nav',v,'f21-kpi');}
function reportCurrency(){const ds=documents().filter(d=>d.status==='posted'),codes=[...new Set(ds.map(d=>d.currency).concat(db().accounts.map(a=>a.currency)))].filter(Boolean);return table(['العملة','المطلوب من العملاء','التزامات الموردين','مستحقات ومصاريف','أرصدة الصندوق والبنك'],codes.map(c=>'<tr><td>'+E(c)+'</td><td>'+cash(ds.filter(d=>d.kind==='customer'&&d.currency===c).reduce((s,d)=>s+remaining(d),0),c)+'</td><td>'+cash(ds.filter(d=>d.kind==='vendor'&&d.currency===c).reduce((s,d)=>s+remaining(d),0),c)+'</td><td>'+cash(ds.filter(d=>['employee','expense'].includes(d.kind)&&d.currency===c).reduce((s,d)=>s+remaining(d),0),c)+'</td><td>'+cash(db().accounts.filter(a=>a.currency===c).reduce((s,a)=>s+balance(a.id),0),c)+'</td></tr>').join(''));}
function homeHtml(){const ds=documents(),inv=ds.filter(x=>x.kind==='customer'&&x.status==='posted'&&remaining(x)>0),dues=ds.filter(x=>x.kind!=='customer'&&x.status==='posted'&&remaining(x)>0),review=ds.filter(x=>x.status==='review'),ready=getAccountingPackageTasks().filter(t=>accountingPackageStatusInfo(t).key==='ready'),wait=A(state.salesTasks).filter(t=>!t.parentTaskId&&t.status==='awaiting_invoice');return head('المتابعة المالية','ابدأ بما يحتاج إجراءً. كل مستند مرتبط بمصدره، وكل عملة تظهر وحدها.',B('تحديث','refresh'))+'<div class="f21-kpis">'+metric('مهام تنتظر قرار الفوترة',wait.length,'billing',ready.length+' باقات جاهزة قبل الفوترة')+metric('فواتير تحتاج تحصيلاً',inv.length,'invoices',inv.filter(d=>d.dueDate<today()).length+' تجاوزت الاستحقاق')+metric('التزامات تحتاج تسديداً',dues.length,'payables','موردون وموظفون ومصاريف')+metric('بانتظار قرار الإدارة',review.length,'review','كشف أو مصروف غير معتمد')+'</div>'+(!db().accounts.length?note('لبدء القبض والصرف: أضف صندوقاً أو حساب بنك بعملته ورصيده الافتتاحي الحقيقي. '+B('إعداد الصندوق والبنك','nav','cash')):'')+table(['ما يحتاج متابعة','الخطوة التالية',''],[['الباقات التي اكتملت خدماتها','تراجعها المحاسبة ثم ترسلها للفوترة','packages'],['المبيعات والتحصيل','راجع الفاتورة، ثم سجّل القبض الجزئي أو الكامل','invoices'],['أوامر الشراء والاستلام','استلام المواد لا يعني تسديد ثمنها','vendors'],['طلبات الموارد البشرية','الأجر من كشف معتمد؛ لا يُحسب من عداد بدء العمل','employees']].map(([a,b,v])=>'<tr><td><b>'+a+'</b></td><td>'+b+'</td><td>'+B('فتح','nav',v)+'</td></tr>').join(''))+fold('ملخص مالي حسب العملة',reportCurrency())+fold('ضوابط العمل وحدود هذه النسخة','الاعتماد غير التسديد. لا تجمع العملات. دفعات المورد المقدمة لا تُسجَّل كمصروف ثانٍ عند تسويتها. لا تُسعَّر أمانات الزبائن كملكية للشركة. هذه متابعة مالية تشغيلية وليست دفاتر قانونية أو محرك ضرائب؛ لا توجد فروق عملة أو إهلاك تلقائي.');}
function listFilter(scope=''){return'<div class="f21-filter">'+input('بحث بالمستند أو المستفيد',scope+'f21Search',query)+select('عرض الحالات',scope+'f21Filter',[['open','المفتوحة'],['all','كل السجلات'],['draft','المسودات / المراجعة'],['posted','المعتمدة'],['review','بانتظار الإدارة'],['overdue','المتأخرة'],['paid','المسددة'],['cancelled','الملغاة']],filter)+B('بحث','filter')+'</div>';}
function filterDocs(rows){const s=query.toLowerCase();return rows.filter(d=>(!s||[d.number,d.party,d.reference,d.sourceLabel].join(' ').toLowerCase().includes(s))&&(filter==='all'||filter==='open'&&!['cancelled'].includes(d.status)&&(d.status!=='posted'||remaining(d)>0)||filter==='draft'&&['draft','legacy'].includes(d.status)||filter===d.status||filter==='overdue'&&d.status==='posted'&&remaining(d)>0&&d.dueDate<today()||filter==='paid'&&d.status==='posted'&&remaining(d)===0)).sort((a,b)=>(a.dueDate||'').localeCompare(b.dueDate||''));}
function docsTable(rows){const all=filterDocs(rows),pages=Math.max(1,Math.ceil(all.length/10));pageN=Math.min(pages,Math.max(1,pageN));return table(['المستند / المصدر','المستفيد','الاستحقاق','المبلغ','المتبقي','الحالة',''],all.slice((pageN-1)*10,pageN*10).map(d=>'<tr><td><b>'+E(d.number)+'</b><small>'+E(d.sourceLabel||d.reference||'يدوي')+'</small></td><td>'+E(d.party)+'</td><td>'+stamp(d.dueDate)+(d.status==='posted'&&remaining(d)>0&&d.dueDate<today()?'<small class="f21-warn">متأخر</small>':'')+'</td><td><bdi dir="ltr">'+(d.status==='legacy'?E(d.legacyTotal)+' · العملة تحتاج مراجعة':cash(d.total,d.currency))+'</bdi></td><td>'+(d.status==='posted'?'<bdi dir="ltr">'+cash(remaining(d),d.currency)+'</bdi>':'—')+'</td><td>'+badge(d.status)+'</td><td>'+B('فتح','doc',d.id)+'</td></tr>').join(''))+'<div class="f21-pager"><span>'+all.length+' سجل · صفحة '+pageN+' من '+pages+'</span>'+B('السابق','page',-1)+B('التالي','page',1)+'</div>';}
function vendorsHtml(){return head('الموردون والمشتريات','العروض المعتمدة والاستلام من المصدر نفسه. لا تكتب طلب الشراء مرة ثانية.',B('تحديث','refresh'))+fold('أوامر الشراء المعتمدة — إنشاء فاتورة أو دفعة مقدمة',table(['الأمر / المورد','المعتمد','المرحلة / الاستلام','غير مسوّى من المقدم',''],postedOrders().map(r=>{const m=meta(r),c=m.approval.quote.currency;return'<tr><td><b>'+E(m.orderNo||r.requestNo)+'</b>'+E(m.approval.quote.supplierName)+'</td><td>'+cash(orderCost(r),c)+'</td><td>'+E({approved:'معتمد',ordered:'طُلب من المورد',partial:'استلام جزئي',completed:'استلام مكتمل',deferred:'مؤجل'}[m.phase]||m.phase)+'<small>'+A(m.receipts).length+' سند استلام</small></td><td>'+cash(availableAdvance(r.id),c)+'</td><td><div class="f21-actions">'+B('فاتورة مورد','new-bill',r.id)+B('دفعة مقدمة','advance',r.id)+B('المصدر','source-order',r.id)+'</div></td></tr>';}).join('')))+listFilter()+docsTable(documents().filter(d=>d.kind==='vendor'))+fold('الدفعات المقدمة وسجل التسديد',paymentsTable(activePay().filter(p=>p.kind==='supplier_advance'||doc(p.docId)?.kind==='vendor')));}
function employeesHtml(){const source=hrRequests();return head('مستحقات الموظفين','طلبات معتمدة أو وصلت للمحاسبة، وكشوف HR بمبلغ صافٍ يراجعه المدير التنفيذي.',B('+ كشف مستحقات','new-doc','employee','primary'))+fold('طلبات الموارد البشرية الجاهزة للمحاسبة ('+source.length+')',table(['الموظف','الطلب','المبلغ من المصدر','المرحلة',''],source.map(r=>{const exists=documents().find(d=>d.kind==='employee'&&d.sourceId===T(r.id)&&d.status!=='cancelled');return'<tr><td>'+E(r.employeeName)+'</td><td>'+E(hrProTypeLabel(r.type))+'<small>'+E(r.reason)+'</small></td><td>'+E(r.data?.amount)+' '+E(r.data?.currency||r.currency||'العملة غير محددة بالمصدر')+'</td><td>'+E(hrProRequestStage(r))+(exists?'<small>'+E(exists.number)+'</small>':'')+'</td><td>'+B(exists?'فتح المستند':'تجهيز الصرف',exists?'doc':'hr-source',exists?.id||r.id)+(exists&&remaining(exists)===0&&exists.status==='posted'&&r.status==='pending'?B('إتمام خطوة المحاسبة','complete-hr',r.id):'')+'</td></tr>';}).join('')))+listFilter()+docsTable(documents().filter(d=>d.kind==='employee'))+fold('سلف الموظفين المصروفة وإعادتها',table(['الموظف','السند','المصروف','المتبقي للإعادة',''],activePay().filter(p=>p.kind==='payout'&&doc(p.docId)?.kind==='employee'&&doc(p.docId)?.category==='advance').map(p=>'<tr><td>'+E(p.party)+'</td><td>'+E(p.number)+'</td><td>'+cash(p.amount,p.currency)+'</td><td>'+cash(advanceLeft(p.id),p.currency)+'</td><td>'+B('إعادة نقدية للسلفة','employee-return',p.id)+'</td></tr>').join('')))+note('كشف الراتب يسجَّل بصافٍ موثّق من HR، ولا نخصم السلف أو التأخير تلقائياً. لتسديد سلفة من الراتب استخدم «تسوية سلفة من هذا المستحق» داخل الكشف قبل دفع الباقي، وفقط إذا لم تخصمها HR مسبقاً من صافي الكشف.');}
function paymentsTable(rows){return table(['السند / التاريخ','العملية / المستفيد','المبلغ','الحساب / المرجع',''],A(rows).slice().reverse().slice(0,200).map(p=>'<tr><td><b>'+E(p.number)+'</b>'+stamp(p.date)+'</td><td>'+E({receipt:'قبض عميل',payout:'صرف',supplier_advance:'دفعة مورد مقدمة',apply_advance:'تسوية مقدم — دون حركة نقدية',employee_return:'إعادة سلفة نقداً',employee_offset:'تسوية سلفة من الراتب — دون حركة نقدية',transfer:'تحويل بين الحسابات',reversal:'عكس سند'}[p.kind])+'<small>'+E(p.party||'')+(p.reversedAt?' · تم عكسه':'')+'</small></td><td>'+cash(p.amount,p.currency)+'</td><td>'+E(account(p.accountId)?.name||'دون حركة صندوق')+'<small>'+E(p.reference)+'</small></td><td>'+B('تفاصيل','payment',p.id)+'</td></tr>').join(''));}
function cashHtml(){return head('الصندوق والبنك','رصيد كل حساب من افتتاحيته وحركاته. لا تسجيل للقبض أو الصرف بمجرد الموافقة.',(admin()?B('+ حساب / صندوق','new-account','','primary'):'')+B('تحويل بين حسابين','transfer'))+table(['الحساب','العملة','افتتاحي / التاريخ','الرصيد الحالي',''],db().accounts.map(a=>'<tr><td><b>'+E(a.name)+'</b>'+E(a.type==='bank'?'بنك':'صندوق')+'</td><td>'+a.currency+'</td><td>'+cash(a.opening,a.currency)+'<small>'+stamp(a.openingDate)+'</small></td><td><b>'+cash(balance(a.id),a.currency)+'</b></td><td>'+B('كشف الحساب','account',a.id)+'</td></tr>').join(''))+fold('آخر 200 حركة — القبض والصرف والتحويل',paymentsTable(db().payments));}
function settingsHtml(){if(!admin())return head('إعدادات المحاسبة','تعديل فترة الإقفال والأرصدة الافتتاحية متاح للإدارة فقط.')+note('مقفلة حتى: '+stamp(db().settings.lockedThrough));return head('إعدادات المحاسبة','إعدادات واضحة دون تغيير أرقام سابقة.')+note('الفواتير القديمة لا تُرحَّل تلقائياً ولا نفترض عملتها. تحتاج مراجعتها من «فواتير العملاء». الرصيد الافتتاحي لكل صندوق مدخل صريح وليس رقماً تجريبياً.')+'<div class="f21-grid">'+dates('إقفال العمليات حتى تاريخ — اختياري','f21Lock',db().settings.lockedThrough||'')+'</div>'+B('حفظ فترة الإقفال','lock','','primary')+fold('قواعد التسجيل','لا تغيّر العملات الأسعار تلقائياً. لا يمكن الصرف بما يتجاوز رصيد الحساب في تاريخ الحركة. المسودات قابلة للتعديل، والمعتمد يُلغى أو يُعكس بسبب محفوظ. المرفقات محلية في متصفحك ولا تنتقل بإرسال HTML. أمانات العملاء ليست مشتريات ولا أصلاً مالياً للشركة. الضريبة قيمة مكتوبة في المستند فقط؛ لا يُصدر التطبيق إقرارات ضريبية.');}
function reportsHtml(){return head('التقارير وكشوف الحساب','المبالغ من المستندات المعتمدة والحركات المسجلة فقط؛ لا أرباح تقديرية من بيانات ناقصة.',B('معاينة الملخص','print-summary'))+reportCurrency()+fold('كشف مستفيد',select('المستفيد','f21Party',[['','اختر المستفيد'],...[...new Set(documents().filter(d=>d.status==='posted').map(d=>d.party))].map(n=>[n,n])])+B('عرض الكشف','statement'))+fold('سجل التدقيق — آخر 100 إجراء',table(['التاريخ','بواسطة','الإجراء'],db().audit.slice(-100).reverse().map(a=>'<tr><td>'+E(a.at.replace('T',' ').slice(0,19))+'</td><td>'+E(a.by)+'</td><td>'+E(a.description)+'</td></tr>').join('')));}
function render(){mount();const p=Q('f21Page');
 if(view==='assignment'){hideLegacy();p.hidden=true;const fold=taskContainer();fold.hidden=false;fold.open=true;Q('accountingTasksContent').style.display='block';navActive('');window.renderProductiveDistributionBoard('accounting');MoshUI15.tabState('accounting','assign');return;}
 hideLegacy();p.hidden=false;navActive(view);MoshUI15.tabState('accounting','');if(!finance()){p.innerHTML=head('المحاسبة','المعلومات المالية متاحة للمحاسبة والإدارة فقط.');return;}
 if(view==='packages'||view==='billing'){p.hidden=true;old.open(view);if(view==='billing'){const n=Q('accountingBillingContent');if(!Q('f21BillingHelp'))n.insertAdjacentHTML('afterbegin','<div id="f21BillingHelp" class="f21">'+note('حافظنا على «تمت الفوترة» و«غير بحاجة للفوترة» والأرشيف. إصدار الفاتورة وتحصيلها مرحلتان مستقلتان. '+B('فواتير العملاء','nav','invoices'))+'</div>');}return;}
 p.innerHTML=view==='home'?homeHtml():view==='invoices'?head('فواتير العملاء والتحصيل','المسودات لا تدخل الذمم حتى مراجعتها واعتمادها. القبض يرتبط بالفاتورة نفسها.',B('+ فاتورة عميل','new-invoice','','primary'))+listFilter()+docsTable(documents().filter(d=>d.kind==='customer')):view==='payables'?head('التزامات تحتاج تسديداً','كل المستحقات المعتمدة غير المسددة: الموردون والموظفون والمصاريف.')+listFilter()+docsTable(documents().filter(d=>d.kind!=='customer'&&d.status==='posted'&&remaining(d)>0)):view==='vendors'?vendorsHtml():view==='employees'?employeesHtml():view==='expenses'?head('المصاريف','للمصاريف المستقلة المعتمدة؛ فواتير المشتريات لا تُدخل هنا مرة ثانية.',B('+ طلب مصروف','new-doc','expense','primary'))+listFilter()+docsTable(documents().filter(d=>d.kind==='expense')):view==='cash'?cashHtml():view==='reports'?reportsHtml():view==='review'?head('مستندات بانتظار الإدارة','الإدارة تعتمد الكشف أو تعيده للتصحيح.')+docsTable(documents().filter(d=>d.status==='review')):settingsHtml();Q('crumb').innerHTML='<b>قسم المحاسبة</b> / '+E(({home:'لوحة التحكم',payables:'التزامات تحتاج تسديداً',invoices:'فواتير العملاء',vendors:'الموردون والمشتريات',employees:'مستحقات الموظفين',expenses:'المصاريف',cash:'الصندوق والبنك',reports:'التقارير',review:'اعتماد المستحقات والمصاريف',settings:'الإعدادات'})[view]);if(view==='home')MoshUI15.tabState('accounting','distribution');}
// ---- Forms use the same persisted records. Changes are drafts until successful save. ----
function uploadInput(files){return fold('المرفقات / إثبات المستند',A(files).map(f=>'<div class="f21-file"><span>'+E(f.name)+'</span>'+B('إزالة من المسودة','remove-file',f.key)+'</div>').join('')+'<label class="f21-field"><span>إضافة صورة أو PDF — تحفظ خارج ملف التطبيق</span><input id="f21Files" type="file" accept="image/*,application/pdf" multiple></label>');}
async function upload(files){const kept=C(A(files)),created=[];try{for(const file of [...(Q('f21Files')?.files||[])]){guard(/^(image\/|application\/pdf)/.test(file.type),'المرفقات المقبولة صور أو PDF فقط.');guard(file.size<=15*1024*1024,'المرفق أكبر من 15 ميغابايت.');const key=uid('FIN21');await storeAttachmentRecord({key,scope:'finance21',blob:file,name:file.name,type:file.type,size:file.size,createdAt:now()});created.push(key);kept.push({key,name:file.name,type:file.type,size:file.size});}return{files:kept,created};}catch(e){await cleanupFiles(created);throw e;}}
async function cleanupFiles(keys){if(!keys.length)return;try{const d=await openAttachmentsDB();await new Promise((resolve,reject)=>{const t=d.transaction(ATTACHMENTS_STORE,'readwrite');keys.forEach(k=>t.objectStore(ATTACHMENTS_STORE).delete(k));t.oncomplete=resolve;t.onerror=()=>reject(t.error);});d.close();}catch(e){console.warn('Finance unattached file cleanup',e);}}
async function downloadFile(key){guard(finance()||hr());const r=await getAttachmentRecord(key);guard(r?.blob,'المرفق غير موجود بهذا المتصفح. أرسل المرفق الأصلي أو افتح نفس جهاز التسجيل.');const u=URL.createObjectURL(r.blob);modal('تحميل المرفق',note('اضغط الرابط لتنزيل الملف من المتصفح. فتحه لا يغيّر المستند.')+'<p><a class="f21-btn primary" href="'+u+'" download="'+E(r.name)+'">تحميل '+E(r.name)+'</a></p>'+'<a class="f21-btn" href="'+u+'" target="_blank" rel="noopener">فتح المرفق</a>');setTimeout(()=>URL.revokeObjectURL(u),120000);}
function linesHtml(lines,locked=false){return table(['البند','الكمية','سعر الوحدة','خصم %','ضريبة %',locked?'':''],A(lines).map((l,i)=>'<tr data-fin-line="'+i+'"><td><input data-line="name" value="'+E(l.name)+'" '+(locked?'readonly':'')+'></td><td><input data-line="qty" inputmode="decimal" value="'+E(l.qty)+'"></td><td><input data-line="price" inputmode="decimal" value="'+E(l.price)+'" '+(locked?'readonly':'')+'></td><td><input data-line="discount" inputmode="decimal" value="'+E(l.discount||0)+'" '+(locked?'readonly':'')+'></td><td><input data-line="tax" inputmode="decimal" value="'+E(l.tax||0)+'" '+(locked?'readonly':'')+'></td><td>'+(!locked?B('حذف','remove-line',i):'')+'</td></tr>').join(''));}
function collectLines(){return [...(Q('f21Lines')?.querySelectorAll('[data-fin-line]')||[])].map(row=>{const oldLine=form?.lines?.[+row.dataset.finLine]||{};const l={...oldLine};row.querySelectorAll('[data-line]').forEach(el=>l[el.dataset.line]=el.value);return l;});}
function liveTotal(){if(!form||!['customer','vendor'].includes(form.kind))return;try{const c=V('f21Currency');currency(c);const t=totals(collectLines(),c);Q('f21Total').textContent='الصافي '+cash(t.net,c)+' · الضريبة '+cash(t.tax,c)+' · الإجمالي '+cash(t.total,c);}catch(e){if(Q('f21Total'))Q('f21Total').textContent='أكمل العملة وأسعار البنود لعرض الإجمالي.';}}
function invoiceEditor(id='',quoteId=''){guard(finance());const d=id?doc(id):null;guard(!id||d&&['draft','legacy'].includes(d.status),'الفاتورة غير قابلة للتعديل.');const inv=id?A(state.invoices).find(i=>'INV:'+i.id===id):null,q=quoteId?A(state.quotations).find(x=>T(x.id)===T(quoteId)):null;let lines=d?.lines?C(d.lines):q?A(q.lines).filter(l=>l.type==='product').map(l=>({name:l.product||l.description,description:l.description||'',qty:l.qty,price:l.price,discount:l.discount||0,tax:l.tax||0})):[{name:d?'قيمة الفاتورة السابقة':'',qty:1,price:d?.legacyTotal??'',discount:0,tax:0}];const ctx={kind:'customer',id,sourceId:d?.sourceId||quoteId||'',files:C(A(d?.files)),lines,taskIds:A(d?.taskIds),token:uid('FORM')};const quotes=A(state.quotations).filter(x=>x.status==='order');modal(id?'مراجعة / تعديل فاتورة العميل':'فاتورة عميل جديدة',(d?.status==='legacy'?note('المبلغ السابق محفوظ. اختر عملته وتاريخ الفاتورة قبل الاعتماد؛ لا نحول السجل القديم تلقائياً إلى ذمة.'):'')+'<div class="f21-grid">'+select('ربط بعرض مبيعات معتمد','f21Quote',[['','بدون ربط تلقائي'],...quotes.map(q=>[T(q.id),q.number+' · '+q.customer])],ctx.sourceId)+customerSelect22(d,q)+select('العملة *','f21Currency',[['','اختر العملة'],...CUR],d?.currency||q?.currency||'')+input('مرجع خارجي / أمر مبيعات','f21Reference',d?.sourceLabel||q?.number||'')+dates('تاريخ الفاتورة *','f21Date',d?.date||today())+dates('تاريخ الاستحقاق *','f21Due',d?.dueDate||today())+'</div><h3>الخدمات والبنود</h3><div id="f21Lines">'+linesHtml(lines)+'</div>'+B('+ بند','add-line')+'<p class="f21-total" id="f21Total"></p>'+textarea('ملاحظات وشروط الفاتورة','f21Notes',d?.notes||'')+uploadInput(ctx.files),B('حفظ المسودة وإغلاق','save-doc','','primary'),ctx);liveTotal();}
function billEditor(orderId,id=''){guard(finance());const r=ops(orderId),m=meta(r),d=id?doc(id):null;guard(r&&m.approval,'أمر الشراء غير معتمد.');guard(!d||d.status==='draft','الفاتورة مقفلة.');const q=m.approval.quote;const lines=d?.lines?C(d.lines):q.lines.map(l=>({...l,qty:l.qty}));if(!d&&q.shipping>0)lines.push({name:'توصيل / تكاليف العرض المعتمدة',qty:1,price:q.shipping,discount:0,tax:0,shipping:true});const ctx={kind:'vendor',id,sourceId:r.id,approvalId:m.approval.id,partyId:q.supplierId,lines,files:C(A(d?.files)),token:uid('FORM')};modal('فاتورة مورد — '+(m.orderNo||r.requestNo),note('المورد والأسعار والعملة من العرض المعتمد. حدد الكمية المفوترة. لا تعتمد الفاتورة قبل تسجيل استلام يغطي البنود؛ للشراء قبل الاستلام استخدم دفعة مقدمة.')+'<div class="f21-grid">'+input('المورد','f21Party',q.supplierName,'text','readonly')+input('رقم فاتورة المورد *','f21Reference',d?.reference||'')+select('العملة المعتمدة','f21Currency',[[q.currency,q.currency]],q.currency)+input('مرجع أمر الشراء','f21SourceLabel',m.orderNo||r.requestNo,'text','readonly')+dates('تاريخ فاتورة المورد *','f21Date',d?.date||today())+dates('الاستحقاق *','f21Due',d?.dueDate||today())+'</div><div id="f21Lines">'+linesHtml(lines,true)+'</div><p id="f21Total" class="f21-total"></p>'+textarea('ملاحظات المطابقة','f21Notes',d?.notes||'')+uploadInput(ctx.files),B('حفظ المسودة وإغلاق','save-doc','','primary'),ctx);liveTotal();}
function payableEditor(kind,id='',hrId=''){guard(kind==='employee'?(hr()||finance()):finance());const d=id?doc(id):null,r=hrId?sourceHr(hrId):null;guard(!id||d?.status==='draft','المستند مقفل.');const people=A(state.staffProfiles);const ctx={kind,id,sourceId:d?.sourceId||T(r?.id),files:C(A(d?.files)),token:uid('FORM')};modal(kind==='employee'?'كشف / مستحق موظف':'طلب مصروف مستقل',note(kind==='employee'?'اسم الموظف من ملف الموارد البشرية. المبلغ هو الصافي من الكشف أو الطلب، دون حساب راتب أو خصم آلي. الكشف الجديد يرسل للإدارة، والطلب السابق يحتفظ بموافقاته.':'لا تسجّل هنا فاتورة مشتريات موجودة عند الموردين. المصروف الجديد ينتظر اعتماد الإدارة قبل الصرف.')+'<div class="f21-grid">'+(kind==='employee'?select('الموظف *','f21Employee',[['','اختر الموظف'],...people.map(p=>[T(p.id),p.name])],d?.partyId||T(r?.employeeId)):input('المستفيد / جهة الصرف *','f21Party',d?.party||''))+input('مرجع الكشف / المستند *','f21Reference',d?.reference||r?.id||'')+select('العملة *','f21Currency',[['','اختر العملة'],...CUR],d?.currency||r?.data?.currency||r?.currency||'')+input('المبلغ الصافي *','f21Amount',d?units(d.total,d.currency):r?.data?.amount??'','text','inputmode="decimal"')+dates('تاريخ المستند *','f21Date',d?.date||today())+dates('الاستحقاق *','f21Due',d?.dueDate||today())+(kind==='employee'?input('شهر الكشف عند عدم وجود طلب سابق *','f21Period',d?.period||today().slice(0,7),'text','placeholder="2026-09"'):select('ربط بمهمة — اختياري','f21Task',[['','مصروف عام'],...A(state.salesTasks).filter(t=>!t.parentTaskId).map(t=>[T(t.id),MoshTaskUI.label(t)])],d?.taskId||''))+select('التصنيف','f21Category',(kind==='employee'?[['salary','مستحقات شهرية'],['advance','سلفة موظف'],['reward','مكافأة معتمدة'],['settlement','تسوية نهائية']]:[['transport','نقل'],['communication','اتصالات'],['maintenance','صيانة'],['office','مصروف مكتبي'],['other','أخرى']]),d?.category||r?.type||'')+'</div>'+textarea('الشرح ومرجع الاعتماد *','f21Notes',d?.notes||r?.reason||'')+uploadInput(ctx.files),B('حفظ المسودة وإغلاق','save-doc','','primary'),ctx);if(r||d?.sourceId){Q('f21Employee').disabled=true;Q('f21Amount').readOnly=true;Q('f21Category').disabled=true;}if(kind==='employee'&&!r&&!d){Q('f21Category').value='salary';}}
async function saveDocForm(){const f=form;guard(f,'النموذج غير موجود.');let data={...f,currency:V('f21Currency'),date:V('f21Date'),dueDate:V('f21Due'),party:V('f21Party'),reference:V('f21Reference'),sourceLabel:V('f21SourceLabel')||V('f21Reference'),notes:V('f21Notes'),amount:V('f21Amount'),category:V('f21Category'),period:V('f21Period'),taskId:V('f21Task')};if(f.kind==='customer'||f.kind==='vendor')data.lines=collectLines();if(f.kind==='customer'){data.sourceId=V('f21Quote');data.sourceLabel=V('f21Reference');}if(f.kind==='employee'){const p=A(state.staffProfiles).find(x=>T(x.id)===V('f21Employee'));data.party=p?.name;data.partyId=T(p?.id);data.department=p?.department||'';}if(f.kind==='vendor'){if(Q('x22Supplier')){data.partyId=V('x22Supplier');data.party=master22('vendor:'+data.partyId)?.name||'';}data.ledgerAccount22=V('x22Classification')||'1590';}const u=await upload(f.files);data.files=u.files;try{const id=await tx(()=>f.kind==='customer'?saveCustomer(data):savePayable(data));await close(true);if(Q('accountingApp').classList.contains('active')){view=f.kind==='customer'?'invoices':f.kind==='vendor'?'vendors':f.kind==='employee'?'employees':'expenses';render();}else if(Q('hrApp')?.classList.contains('active'))hrWorkspace();toast('تم حفظ المسودة. افتحها للمراجعة والاعتماد.');return id;}catch(e){await cleanupFiles(u.created);throw e;}}
function detail(id){const d=doc(id);guard(d,'المستند غير موجود.');guard(finance()||hr()&&d.kind==='employee');let actions='';if(['draft','legacy'].includes(d.status))actions+=B('تعديل','edit-doc',id);if(d.status==='draft')actions+=B(['customer','vendor'].includes(d.kind)||d.sourceId?'اعتماد المستند':'إرسال للإدارة','submit',id,'primary');if(d.status==='review'&&admin())actions+=B('قرار الإدارة','decide',id,'primary');if(finance()&&d.status==='posted'&&remaining(d)>0)actions+=B(d.kind==='customer'?'تسجيل قبض':'تسجيل صرف','pay',id,'primary')+(d.kind==='vendor'&&availableAdvance(d.sourceId)>0?B('تسوية من الدفعة المقدمة','apply',id):'')+(d.kind==='employee'&&['salary','settlement'].includes(d.category)?B('تسوية سلفة من هذا المستحق','offset',id):'');if(d.status!=='legacy'&&d.status!=='cancelled'&&(finance()||d.status==='draft'))actions+=B('إلغاء موثّق','cancel-doc',id,'danger');actions+=B('معاينة / طباعة','print-doc',id);const base=docPaper(d,false);modal(d.number+' — '+d.party,'<div class="f21-actions">'+badge(d.status)+(d.status==='posted'?'<span>المتبقي '+cash(remaining(d),d.currency)+'</span>':'')+'</div>'+base+fileSection(d.files)+(finance()?fold('القبض / الصرف والتسويات المرتبطة',paymentsTable(db().payments.filter(p=>p.docId===d.id))):'')+(d.kind==='vendor'?B('الأمر والاستلام الأصلي','source-order',d.sourceId):'')+(d.sourceId&&d.kind==='employee'?note('مرتبط بطلب الموارد البشرية '+E(d.sourceId)+'. تسجيل الصرف لا يعيد إنشاء الطلب.'):''),actions);}
function docPaper(d,print=true){const legacy=d.status==='legacy';return'<div class="'+(print?'f21-paper':'f21-document')+'"><header><b>MOSH GROUP</b><span>'+E(d.number)+'</span></header><h2>'+E(({customer:'فاتورة عميل',vendor:'فاتورة مورد مسجلة',employee:'كشف مستحق موظف',expense:'مستند مصروف'})[d.kind])+'</h2><p>'+E(statusName(d.status))+(d.status==='draft'?' — غير معتمد':'')+'</p><div class="f21-grid"><div>المستفيد: <b>'+E(d.party)+'</b></div><div>المصدر: '+E(d.sourceLabel||d.reference||'—')+'</div><div>التاريخ: '+stamp(d.date)+'</div><div>الاستحقاق: '+stamp(d.dueDate)+'</div></div>'+(d.lines?.length?table(['البند','الكمية','السعر','الخصم %','الضريبة %','الإجمالي'],d.lines.map(l=>'<tr><td>'+E(l.name)+'</td><td>'+l.qty+'</td><td>'+E(l.price)+'</td><td>'+l.discount+'</td><td>'+l.tax+'</td><td>'+cash(l.total,d.currency)+'</td></tr>').join('')):'')+'<p class="f21-total">الإجمالي: '+(legacy?E(d.legacyTotal)+' — العملة تحتاج مراجعة':cash(d.total,d.currency))+'</p>'+(d.status==='posted'?'<p>المسدد / المسوّى: '+cash(usedOn(d.id),d.currency)+' · المتبقي: '+cash(remaining(d),d.currency)+'</p>':'')+'<p class="f21-pre">'+E(d.notes)+'</p>'+(d.cancelReason?'<p>سبب الإلغاء: '+E(d.cancelReason)+'</p>':'')+'<footer>نسخة من السجل التشغيلي · '+E(me())+' · '+stamp(today())+'</footer></div>';}
function payForm(kind,id=''){guard(finance());const d=['receipt','payout','apply_advance','employee_offset'].includes(kind)?doc(id):null;const r=kind==='supplier_advance'?ops(id):null;const a=kind==='employee_return'?payment(id):null;const c=d?.currency||meta(r).approval?.quote?.currency||a?.currency||'';const opts=db().accounts.filter(x=>x.active&&(!c||x.currency===c)).map(x=>[x.id,x.name+' · '+x.currency+' · '+cash(balance(x.id),x.currency)]);const title={receipt:'تسجيل قبض عميل',payout:'تسجيل صرف مستحق',supplier_advance:'دفعة مقدمة للمورد',transfer:'تحويل بين صندوق / بنك',apply_advance:'تسوية دفعة مقدمة على الفاتورة',employee_return:'إعادة سلفة الموظف نقداً',employee_offset:'تسوية سلفة من مستحق الموظف'}[kind];const ctx={kind:'money',moneyKind:kind,docId:d?.id||'',sourceId:r?.id||d?.sourceId||'',advanceId:a?.id||'',currency:c,files:[],token:uid('PAYFORM')};const advances=activePay().filter(p=>(kind==='employee_offset'?p.kind==='payout'&&doc(p.docId)?.kind==='employee'&&doc(p.docId)?.category==='advance'&&doc(p.docId)?.partyId===d?.partyId:p.kind==='supplier_advance'&&p.sourceId===d?.sourceId)&&p.currency===c&&advanceLeft(p.id)>0).map(p=>[p.id,p.number+' · '+cash(advanceLeft(p.id),p.currency)]);
 modal(title,note(d?d.number+' · '+E(d.party)+' · المتبقي '+cash(remaining(d),c):r?'دفعة قبل الفاتورة، مرتبطة بأمر شراء معتمد. تسوَّى لاحقاً ولا تُحتسب كمصروف مرتين.':kind==='transfer'?'نقل بين حسابين بنفس العملة فقط. لا يدخل ضمن الإيراد أو المصروف.':'تسجيل مال دخل فعلياً إلى الحساب، وليس خصماً من راتب.')+'<div class="f21-grid">'+(['apply_advance','employee_offset'].includes(kind)?select('السلفة / الدفعة المقدمة','f21Advance',advances):select('الحساب *','f21Account',[['','اختر الحساب'],...opts]))+(kind==='transfer'?select('الحساب المستلم *','f21ToAccount',[['','اختر حساباً آخر'],...opts]):'')+select('العملة *','f21Currency',c?[[c,c]]:[['','اختر العملة'],...CUR],c)+input('المبلغ *','f21PayAmount',d?units(remaining(d),c):a?units(advanceLeft(a.id),c):'','text','inputmode="decimal"')+dates('تاريخ الحركة الفعلية *','f21PayDate')+input('مرجع الإيصال / الدفع *','f21PayReference')+'</div>'+textarea('الشرح / اسم المستلم الفعلي','f21PayNote','')+uploadInput([]),B(['apply_advance','employee_offset'].includes(kind)?'اعتماد التسوية دون صرف جديد':'تسجيل وحفظ السند','save-pay','','primary'),ctx);}
