function showOrder(id){guard(finance());const r=ops(id),m=meta(r),q=m.approval?.quote;guard(q,'لا يوجد اعتماد مالي لهذا الطلب.');modal('مرجع الشراء — '+(m.orderNo||r.requestNo),note('قراءة من المصدر الأصلي. لا تنشئ هذه الصفحة استلاماً أو حركة مخزون.')+'<h3>'+E(q.supplierName)+'</h3><p>المعتمد '+cash(orderCost(r),q.currency)+' · بواسطة '+E(m.approval.by)+'</p>'+table(['البند','المعتمد','المستلم','السعر'],q.lines.map(l=>'<tr><td>'+E(l.name)+'</td><td>'+l.qty+'</td><td>'+A(m.receipts).flatMap(x=>A(x.lines)).filter(x=>x.lineId===l.lineId).reduce((n,x)=>n+x.qty,0)+'</td><td>'+E(l.price)+' '+E(q.currency)+'</td></tr>').join(''))+fileSection(sourceFiles(r)),B('فاتورة مورد','new-bill',r.id)+B('دفعة مقدمة','advance',r.id));}
function accountStatement(id){guard(finance());const a=account(id);guard(a);let b=a.opening;const rows=accountMoves(id).map(r=>{b+=r.amount;return'<tr><td>'+stamp(r.date)+'</td><td>'+E(r.p.number)+'</td><td>'+E(r.p.reference)+'</td><td>'+(r.amount>0?cash(r.amount,a.currency):'—')+'</td><td>'+(r.amount<0?cash(-r.amount,a.currency):'—')+'</td><td>'+cash(b,a.currency)+'</td></tr>';});const html='<h2>كشف '+E(a.name)+'</h2><p>افتتاحي '+cash(a.opening,a.currency)+' في '+stamp(a.openingDate)+'</p>'+table(['التاريخ','السند','المرجع','داخل','خارج','الرصيد'],rows.join(''));modal('كشف حساب الصندوق / البنك',html,B('معاينة وطباعة','print-html'));printContent=html;}
