function doPrint(){guard(finance()||hr());Q('f21Print')?.remove();const el=document.createElement('div');el.id='f21Print';el.className='f21 f21-paper';el.innerHTML=printContent;document.body.append(el);document.documentElement.classList.add('f21-printing');const clean=()=>{document.documentElement.classList.remove('f21-printing');el.remove();};window.addEventListener('afterprint',clean,{once:true});try{window.print();}catch(e){clean();throw e;}setTimeout(clean,120000);}

