function hoursInput23(){return {employeeId:V('p23Employee'),period:V('p23Month'),currency:V('p23Cur'),basis:V('p23Basis'),baseAmount:V('p23Base'),normHours:V('p23Norm'),regularHours:V('p23Regular'),paidHours:V('p23Paid'),overtimeHours:V('p23OT'),overtimeRate:V('p23Multiplier'),bonus:V('p23Bonus'),deductions:V('p23Deduct'),reference:V('p23Ref'),overtimeApproval:V('p23OTRef'),bonusReason:V('p23BonusRef'),deductionReason:V('p23DeductRef'),notes:V('p23Notes')};}
