function hoursHtml23(){const rows=D23().hours.filter(h=>h.period===P23.month&&h.currency===P23.currency&&(!P23.query||h.employeeName.includes(P23.query)));return head('اعتماد ساعات الشهر','HR يراجع الساعات والأجر، ثم يعتمد سجل الشهر. الكشوف تستخدم نسخة الساعات المعتمدة المحفوظة.',btn23('+ سجل ساعات وأجر','hours-form23','','primary')+btn23('كشوف الرواتب الشهرية','nav23','payroll23'))+periodBar23()+table(['الموظف / الشهر','الساعات العادية + المدفوعة','إضافي','المستحق قبل السلف','الحالة',''],rows.map(h=>'<tr><td><b>'+E(h.employeeName)+'</b>'+E(h.period)+'</td><td>'+E(h.regularHours)+' + '+E(h.paidHours)+'</td><td>'+E(h.overtimeHours)+'</td><td>'+cash(h.calculation.net,h.currency)+'</td><td>'+E({draft:'مسودة',approved:'ساعات معتمدة',superseded:'مراجعة سابقة'}[h.status])+'<small>'+E(h.approvedBy||'')+'</small></td><td>'+btn23('التفاصيل','hours-detail23',h.id)+(h.status==='draft'?btn23('تعديل','hours-form23',h.id)+btn23('اعتماد الساعات','approve-hours23',h.id,'primary'):'')+'</td></tr>').join(''))+note('الأجر الشهري ÷ ساعات الشهر التعاقدية × (ساعات عادية + ساعات مدفوعة)، ثم الإضافي والبدلات والاستقطاعات الموثقة. الأجر الساعي يحسب بسعر الساعة. أيام الغياب لا تُخصم ثانية بعد تخفيض الساعات. لا نفترض ساعات شهرية أو مبلغ أجر عند غيابها.');}
function hoursPaper23(h){guard(hr()||finance());guard(h,'سجل الساعات غير موجود.');return '<h2>مراجعة ساعات الشهر — '+E(h.employeeName)+'</h2><p>'+E(h.period)+' · '+E(h.reference)+' · '+E(h.status==='approved'?'معتمد بواسطة '+h.approvedBy:'مسودة غير معتمدة')+'</p>'+table(['البيان','القيمة'],[['ساعات الشهر التعاقدية',h.normHours],['ساعات عادية',h.regularHours],['ساعات مدفوعة دون عمل',h.paidHours],['إضافي معتمد',h.overtimeHours],['أجر عادي ومدفوع',cash(h.calculation.regularPay,h.currency)],['أجر إضافي',cash(h.calculation.overtimePay,h.currency)],['بدلات ومكافآت',cash(h.calculation.bonus,h.currency)],['استقطاعات دون السلف',cash(h.calculation.deductions,h.currency)],['المستحق قبل السلف',cash(h.calculation.net,h.currency)]].map(([a,b])=>'<tr><td>'+E(a)+'</td><td>'+E(b)+'</td></tr>').join(''))+'<p>'+E(h.notes)+'</p>';}
function makeRun23(ids,postDate,dueDate){guard(hr());guard(A(ids).length,'اختر سجلاً معتمداً واحداً على الأقل.');const sheets=[...new Set(ids)].map(h23);guard(sheets.every(h=>h?.status==='approved'),'يوجد سجل ساعات غير معتمد.');const first=sheets[0];guard(sheets.every(h=>h.period===first.period&&h.currency===first.currency),'كل كشف لشهر وعملة واحدة.');postDate=date(postDate);dueDate=date(dueDate);lockDate(postDate);guard(postDate>=endMonth23(first.period)&&postDate<=today(),'تاريخ استحقاق أجر الشهر لا يسبق نهايته ولا يكون مستقبلياً.');guard(dueDate>=postDate,'موعد الصرف قبل الاستحقاق.');const r={id:uid('PAYROLL23'),number:next('PAYROLL',D23().runs),period:first.period,currency:first.currency,date:postDate,dueDate,status:'draft',lines:[],createdAt:now(),createdBy:me()};
 for(const h of sheets){guard(!documents().some(d=>d.kind==='employee'&&d.category==='salary'&&T(d.partyId)===h.employeeId&&d.period===h.period&&d.status!=='cancelled'),'يوجد كشف سابق للموظف '+h.employeeName+' في الشهر نفسه.');const c=calc23(h);guard(JSON.stringify(c)===h.fingerprint,'تغيرت الساعات بعد اعتمادها؛ اعتمد مراجعة صحيحة.');guard(c.net>0,'المستحق صفر للموظف '+h.employeeName+'؛ لا ينشأ قيد مالي صفري.');const id=savePayable({kind:'employee',party:h.employeeName,partyId:h.employeeId,category:'salary',period:h.period,currency:h.currency,date:postDate,dueDate,amount:String(units(c.net,h.currency)),reference:r.number,notes:'استحقاق شهر '+h.period+' من ساعات معتمدة '+h.id+'؛ السلف تسوى منفصلة ولا تخصم من المصروف مرة ثانية.',department:h.department});const d=mutableDoc(id);d.payroll23={runId:r.id,hoursId:h.id,snapshot:C(h),calculation:C(c)};r.lines.push({employeeId:h.employeeId,name:h.employeeName,hoursId:h.id,docId:id,calculation:C(c)});}
 D23().runs.push(r);audit('payroll23-create',r.id,r.number);return r.id;}
let payrollAction23=false;
function runStatus23(r){const ds=r.lines.map(l=>doc(l.docId));return ds.every(d=>d?.status==='cancelled')?'cancelled':ds.every(d=>d?.status==='posted')?'posted':ds.every(d=>d?.status==='review')?'review':'draft';}
function submitRun23(id){guard(hr());const r=run23(id);guard(r&&runStatus23(r)==='draft','الكشف ليس مسودة.');payrollAction23=true;try{for(const l of r.lines){guard(doc(l.docId)?.status==='draft','حالات الكشف غير متوافقة.');submitDoc(l.docId);}r.status='review';r.submittedAt=now();}finally{payrollAction23=false;}audit('payroll23-submit',id,r.number);}
function decideRun23(id,approve,why){guard(admin());const r=run23(id);guard(r&&runStatus23(r)==='review','الكشف ليس بانتظار الإدارة.');guard(T(why),'اكتب ملاحظة المراجعة.');payrollAction23=true;try{for(const l of r.lines)decideDoc(l.docId,approve,why);r.status=approve?'posted':'draft';r.decidedAt=now();r.decidedBy=me();r.decisionReason=why;}finally{payrollAction23=false;}audit('payroll23-decision',id,why);}
function cancelRun23(id,reason){const r=run23(id);guard(r,'الكشف غير موجود.');const st=runStatus23(r);guard(st!=='cancelled','الكشف ملغى سابقاً.');guard(st==='draft'?hr():admin(),'إلغاء الكشف المرسل أو المعتمد من الإدارة فقط.');guard(T(reason),'اكتب سبب إلغاء الكشف.');guard(r.lines.every(l=>usedOn(l.docId)===0),'اعكس صرف الرواتب وتسويات السلف أولاً قبل إلغاء الكشف.');payrollAction23=true;try{for(const l of r.lines)cancelDoc(l.docId,reason);r.status='cancelled';r.cancelReason=reason;r.cancelledAt=now();r.cancelledBy=me();}finally{payrollAction23=false;}audit('payroll23-cancel',id,reason);}
const cancelPre23=cancelDoc;cancelDoc=function(id,reason){guard(!doc(id)?.payroll23||payrollAction23,'ألغِ كشف الرواتب كاملاً من صفحة الكشف، وليس مستحق موظف واحد.');return cancelPre23(id,reason);};
const submitPre23=submitDoc,decidePre23=decideDoc;
submitDoc=function(id){guard(!doc(id)?.payroll23||payrollAction23,'كشوف الرواتب تعتمد مجمّعة من صفحة كشوف الرواتب.');return submitPre23(id);};
