function runPaper23(r){guard(hr()||finance());guard(r,'كشف الرواتب غير موجود.');return '<h2>كشف رواتب شهر '+E(r.period)+'</h2><p>'+E(r.number)+' · '+E(r.currency)+' · '+E({draft:'مسودة',review:'بانتظار اعتماد الإدارة',posted:'معتمد',cancelled:'ملغى'}[runStatus23(r)])+'</p>'+table(['الموظف','عادي ومدفوع','إضافي','بدلات','استقطاعات','استحقاق قبل السلف','المسدّد / المسوّى','المتبقي'],r.lines.map(l=>{const c=l.calculation,d=doc(l.docId);return '<tr><td>'+E(l.name)+'</td>'+[c.regularPay,c.overtimePay,c.bonus,c.deductions,c.net,usedOn(d.id),remaining(d)].map(n=>'<td>'+cash(n,r.currency)+'</td>').join('')+'</tr>';}).join(''))+'<p>المجموع قبل تسوية السلف: '+cash(r.lines.reduce((n,l)=>n+l.calculation.net,0),r.currency)+'</p><p>اعتماد: '+E(r.decidedBy||'لم يعتمد')+' · '+E(r.decisionReason||'')+'</p>';}
function payrollHtml23(){const rows=D23().runs.filter(r=>r.period===P23.month&&r.currency===P23.currency);return head('كشوف الرواتب الشهرية','ساعات معتمدة ← كشف HR ← اعتماد الإدارة وترحيل الاستحقاق ← تسوية السلف والصرف.',btn23('اعتماد ساعات الشهر','nav23','hours23')+btn23('+ تجهيز كشف من الساعات المعتمدة','run-form23','','primary'))+periodBar23()+table(['الكشف / الشهر','عدد الموظفين','الاستحقاق قبل السلف','الحالة',''],rows.map(r=>'<tr><td><b>'+E(r.number)+'</b>'+E(r.period)+'</td><td>'+r.lines.length+'</td><td>'+cash(r.lines.reduce((n,l)=>n+l.calculation.net,0),r.currency)+'</td><td>'+badge(runStatus23(r))+'</td><td>'+btn23('فتح الكشف','run-detail23',r.id)+btn23('طباعة','run-print23',r.id)+'</td></tr>').join(''))+fold('مستحقات وسلف سابقة أو خارج كشف الشهر',btn23('فتح السجلات السابقة والسلف','nav23','employees')+note('المستندات القديمة محفوظة كما هي. لا ينشئ كشف الشهر راتباً مكرراً عن الموظف والشهر نفسه. السلف المصروفة تسوى على الاستحقاق المعتمد من دون تخفيض مصروف الأجر مرة ثانية.'));}
function payrollHome23(hours=false){if(finance()){route(hours?'hours23':'payroll23');return;}guard(hr());goApp('hr');openHRPro('reports');Q('hrProContent').innerHTML='<div class="f21" data-p23-hr="'+(hours?'hours':'runs')+'">'+(hours?hoursHtml23():payrollHtml23())+'</div>';Q('crumb').innerHTML='<b>الموارد البشرية</b> / '+(hours?'اعتماد ساعات الشهر':'كشوف الرواتب الشهرية');}
